<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceso estudiantes</title><style>*{box-sizing:border-box}body{font-family:Arial;background:#eef2ff;color:#172554;padding:24px}.card{max-width:700px;margin:4vh auto;background:#fff;border-radius:20px;padding:28px}label{display:block;font-weight:bold;margin:15px 0 5px}input,select,button{width:100%;padding:13px;border:1px solid #94a3b8;border-radius:9px;font-size:16px}button{margin-top:15px;background:#1d4ed8;color:#fff;border:0;font-weight:bold}.hidden{display:none}.error{color:#b91c1c;margin-top:10px}.test{display:block;padding:14px;margin:10px 0;background:#eff6ff;border-radius:10px}.version{position:fixed;right:12px;bottom:8px;color:#64748b}</style></head><body><main class="card"><h1>Pruebas de estudiantes</h1><section id="login"><label>Código del colegio</label><input id="school" placeholder="Código entregado por el colegio"><button id="find">Buscar colegio</button><p id="schoolName"></p><label>Curso</label><select id="course" disabled></select><label>Estudiante</label><select id="student" disabled></select><label>PIN del curso</label><input id="pin" type="password"><button id="enter">Ingresar</button><p id="error" class="error"></p></section><section id="panel" class="hidden"><h2 id="welcome"></h2><div id="tests"></div><button id="logout">Salir</button></section></main><div class="version">v2.1.0</div><script>
const api='portal_estudiante_api.php',school=document.querySelector('#school'),course=document.querySelector('#course'),student=document.querySelector('#student'),error=document.querySelector('#error');school.value=new URLSearchParams(location.search).get('colegio')||'';async function req(url,opt){const r=await fetch(url,opt);return r.json()}find.onclick=async()=>{const x=await req(api+'?action=courses&colegio='+encodeURIComponent(school.value));if(!x.ok){error.textContent=x.error;return}schoolName.textContent=x.colegio;course.disabled=false;course.innerHTML='<option value="">Selecciona el curso</option>'+x.cursos.map(c=>'<option value="'+c.id+'">'+c.nombre+'</option>').join('')};course.onchange=async()=>{const x=await req(api+'?action=students&colegio='+encodeURIComponent(school.value)+'&curso='+course.value);student.disabled=false;student.innerHTML='<option value="">Selecciona tu nombre</option>'+x.estudiantes.map(s=>'<option value="'+s.public_id+'">'+s.nombre+'</option>').join('')};enter.onclick=async()=>{const x=await req(api,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'login',colegio:school.value,curso:course.value,estudiante:student.value,pin:pin.value})});if(!x.ok){error.textContent=x.error;return}session()};async function session(){const x=await req(api+'?action=session');if(!x.authenticated)return;login.classList.add('hidden');panel.classList.remove('hidden');welcome.textContent=x.estudiante.nombre+' — '+x.estudiante.curso;tests.innerHTML=x.pruebas.length?x.pruebas.map(p=>'<a class="test" href="rendir_prueba.php?id='+p.id+'">'+p.asignatura+': '+p.titulo+'</a>').join(''):'No hay pruebas asignadas.'}logout.onclick=async()=>{await req(api,{method:'POST',headers:{'Content-Type':'application/json'},body:'{"action":"logout"}'});location.reload()};if(school.value)find.click();session();
</script></body></html>
